// @vitest-environment node
//
// `Event.astro` pulls in `Layout` → `MetaTags.astro`, which computes a
// canonical URL against `Astro.site`. `experimental_AstroContainer.create()`
// leaves `Astro.site` undefined (the container defaults elide `site`), so
// `new URL(path, undefined)` throws. We mock `@/components/common/MetaTags.astro`
// with an on-disk Astro stub that drops all SEO/head computation and renders
// nothing — keeping the test about the Event markup, not the Layout head.
import { describe, expect, it, vi } from 'vitest'
import type { CollectionEntry } from 'astro:content'
import Event from '@/components/blocks/Event.astro'
import imageMetadata from '@/assets/events/fit.jpg'
import { EventCustomFieldType, PaymentMethod } from '@/types'
import { render } from '../lib/container'

// vi.mock is hoisted above the static imports above by the vitest transform,
// so Event.astro resolves the mocked MetaTags module during SSR.
vi.mock('@/components/common/MetaTags.astro', async () => await import('../lib/MetaTagsStub.astro'))

// A minimal `CollectionEntry<'events'>`-shaped fixture. The `image` field
// needs to be an `ImageMetadata`; we reuse a real on-disk image and overwrite
// `src` with an absolute URL so `new URL(src, undefined)` (where `Astro.site`
// is undefined inside the container) still resolves cleanly. The fixture is
// typed as `unknown as CollectionEntry<'events'>` rather than `any` so the
// Z-typed `entry.data` shape surfaces type errors on field access.
const entryData = {
  id: 'evt-1',
  name: 'Rückenfit',
  image: { ...imageMetadata, src: 'https://example.com/img.jpg' },
  sortIndex: 1,
  shortDescription: 'Pilates für den Rücken',
  description: '<p>Ein sanfter Kurs.</p>',
  location: 'Clubhaus',
  dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'],
  duration: '60 Min',
  priceMember: '40 €',
  priceNonMember: '60 €',
  externalOperator: false,
  customFields: [{ name: 'Rückenbeschwerden', type: EventCustomFieldType.Text }],
  paymentMethod: PaymentMethod.SepaDirectDebit,
} as CollectionEntry<'events'>['data']

function buildEntry(
  overrides: Partial<CollectionEntry<'events'>['data']> = {},
): CollectionEntry<'events'> {
  return {
    id: 'evt-1',
    collection: 'events',
    data: { ...entryData, ...overrides },
  } as unknown as CollectionEntry<'events'>
}

async function renderEvent(
  overrides: Partial<CollectionEntry<'events'>['data']> = {},
  props: Record<string, unknown> = {},
) {
  return render(Event, {
    props: {
      type: 'events' as const,
      entry: buildEntry(overrides),
      newsletterDescription: 'Erhalte automatisch eine E-Mail sobald neue Events online sind.',
      newsletterText: 'Ich möchte über zukünftige Events per E-Mail informiert werden',
      schemaType: 'Event' as const,
      ...props,
    },
  })
}

describe('Event.astro', () => {
  it('wraps the page in the event identifier stamped on the root <div>', async () => {
    const { $ } = await renderEvent()
    expect($('div[data-identifier="evt-1"]')).toHaveLength(1)
  })

  it('renders the "Beschreibung" section header and the description HTML verbatim', async () => {
    const { $ } = await renderEvent()
    expect($('#beschreibung h2').text()).toBe('Beschreibung')
    expect($('#beschreibung > div > div').html()).toContain('<p>Ein sanfter Kurs.</p>')
  })

  it('emits the Details list with the expected set of detail ids', async () => {
    const { $ } = await renderEvent()
    const titles = $('#details [data-title]')
      .toArray()
      .map((el) => $(el).attr('data-title'))
    expect(titles).toContain('availability')
    expect(titles).toContain('dates')
    expect(titles).toContain('duration')
    expect(titles).toContain('price')
    expect(titles).toContain('location')
  })

  it('renders the price as two member/non-member rows when prices differ', async () => {
    const { $ } = await renderEvent({ priceMember: '40 €', priceNonMember: '60 €' })
    expect($('#details [data-title="price"]')).toHaveLength(2)
    const priceLabels = $('#details [data-label="price"]')
      .toArray()
      .map((el) => $(el).text())
    expect(priceLabels).toEqual(['40 €', '60 €'])
  })

  it('collapses the price into a single "Kostenlos" row when both prices are "0 €"', async () => {
    const { $ } = await renderEvent({ priceMember: '0 €', priceNonMember: '0 €' })
    expect($('#details [data-title="price"]')).toHaveLength(1)
    expect($('#details [data-label="price"]').text()).toBe('Kostenlos')
  })

  it('shows the dates detail as "Termine" (plural) for two dates, "Termin" (singular) for one', async () => {
    const { $: $multi } = await renderEvent({
      dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'],
    })
    expect($multi('#details [data-title="dates"]').text()).toBe('Termine')

    const { $ } = await renderEvent({ dates: ['2024-04-08T18:00:00Z'] })
    expect($('#details [data-title="dates"]').text()).toBe('Termin')
  })

  it('renders the "Termine" section with the same number of <li> entries as dates (multi-date case)', async () => {
    const { $ } = await renderEvent({ dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'] })
    // Two date strings → two <li> rows total (split across two <ul> columns,
    // first column holds ceil(n/2), the second the remainder).
    expect($('main li')).toHaveLength(2)
  })

  it('stamps the Anmeldung form with the standard input roster plus the SEPA-specific fields', async () => {
    const { $ } = await renderEvent()
    // Mandatory personal fields. Use `form#form` to scope inside the booking
    // form; the hidden NewsletterCard teaser under #newsletter-card renders
    // its own form with another `#email`-id input from NewsletterCard.
    for (const id of ['firstname', 'lastname', 'street', 'plz', 'email', 'phone', 'comment']) {
      expect($(`#anmeldung form#form #${id}`)).toHaveLength(1)
    }
    // SEPA-mandate fields appear only because paymentMethod is SepaDirectDebit.
    expect($('#anmeldung form#form input[data-iban-validation]#iban')).toHaveLength(1)
    expect($('#anmeldung form#form #sepa_mandate')).toHaveLength(1)
  })

  it('omits the IBAN / SEPA mandate fields when paymentMethod is BankTransfer', async () => {
    const { $ } = await renderEvent({ paymentMethod: PaymentMethod.BankTransfer })
    expect($('#anmeldung form#form input[data-iban-validation]')).toHaveLength(0)
    expect($('#anmeldung form#form #sepa_mandate')).toHaveLength(0)
  })

  it('renders one custom-field input per eventCustomField entry', async () => {
    const { $ } = await renderEvent({
      customFields: [
        { name: 'Rückenbeschwerden', type: EventCustomFieldType.Text },
        { name: 'Teilnehmer', type: EventCustomFieldType.Number, minValue: 1, maxValue: 4 },
      ],
    })
    expect($('#anmeldung form#form input#customfield')).toHaveLength(2)
    // Number-typed custom field forwards `min` / `max` through the spread attrs.
    const numberField = $('#anmeldung form#form input#customfield').toArray()[1]
    expect($(numberField).attr('type')).toBe('number')
    expect($(numberField).attr('min')).toBe('1')
    expect($(numberField).attr('max')).toBe('4')
  })

  it('emits three consent checkboxes (member, newsletter, consent)', async () => {
    const { $ } = await renderEvent()
    expect($('#anmeldung form#form #member')).toHaveLength(1)
    expect($('#anmeldung form#form #newsletter')).toHaveLength(1)
    expect($('#anmeldung form#form #consent')).toHaveLength(1)
    // All three render as type="checkbox".
    expect($('#anmeldung form#form input#member[type="checkbox"]')).toHaveLength(1)
    expect($('#anmeldung form#form input#consent[type="checkbox"]')).toHaveLength(1)
  })

  it('embeds the NewsletterCard teaser with the supplied newsletter copy', async () => {
    const { $ } = await renderEvent()
    const teaser = $('#newsletter-card')
    expect(teaser).toHaveLength(1)
    expect(teaser.find('p').first().text()).toContain('Erhalte automatisch')
  })

  it('renders the Anmeldung section with its identifier (the booking flow reveals it client-side)', async () => {
    // Visible-vs-hidden is a styling concern — exercised through Tailwind's
    // `hidden` utility which is mutable CSS, not DOM structure. Asserting on
    // the class string would rot for styling reasons per the spec, so we
    // assert only that the section is stamped with its identifier.
    const { $ } = await renderEvent()
    expect($('#anmeldung')).toHaveLength(1)
  })
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import {
  checkRequiredInput,
  checkRequiredSelect,
  clearCustomValidityOnInput,
  clearCustomValidityOnSelect,
  validateIbanInput,
} from '@/client/forms'

const VALID_IBAN = 'DE89 3704 0044 0532 0130 00'
const MALFORMED_IBAN = 'DE00 0000 0000 0000 0000 00'
const IBAN_ERROR = 'Bitte gib eine gültige IBAN ein.'

type Kind = 'Input' | 'Select' | 'Textarea'
// deno-style "constructor whose prototype we index for a string-keyed property"
type AnyPrototypeCtor = { prototype: any }

const PROTO: Record<Kind, AnyPrototypeCtor> = {
  Input: HTMLInputElement,
  Select: HTMLSelectElement,
  Textarea: HTMLTextAreaElement,
}

type ValidityMock = ReturnType<typeof vi.fn>

interface Stubs {
  set: Record<Kind, ValidityMock>
  report: Record<Kind, ValidityMock>
  restore: () => void
}

function stubValidity(): Stubs {
  const set: Record<Kind, ValidityMock> = {
    Input: vi.fn(),
    Select: vi.fn(),
    Textarea: vi.fn(),
  }
  const report: Record<Kind, ValidityMock> = {
    Input: vi.fn(() => false),
    Select: vi.fn(() => false),
    Textarea: vi.fn(() => false),
  }
  const originals = (Object.keys(PROTO) as Kind[]).map((kind) => ({
    kind,
    setDesc: Object.getOwnPropertyDescriptor(PROTO[kind].prototype, 'setCustomValidity'),
    reportDesc: Object.getOwnPropertyDescriptor(PROTO[kind].prototype, 'reportValidity'),
  }))
  for (const kind of Object.keys(PROTO) as Kind[]) {
    Object.defineProperty(PROTO[kind].prototype, 'setCustomValidity', {
      configurable: true,
      value: set[kind],
    })
    Object.defineProperty(PROTO[kind].prototype, 'reportValidity', {
      configurable: true,
      value: report[kind],
    })
  }
  return {
    set,
    report,
    restore: () => {
      for (const { kind, setDesc, reportDesc } of originals) {
        const proto = PROTO[kind].prototype as any
        if (setDesc) Object.defineProperty(proto, 'setCustomValidity', setDesc)
        else delete proto.setCustomValidity
        if (reportDesc) Object.defineProperty(proto, 'reportValidity', reportDesc)
        else delete proto.reportValidity
      }
    },
  }
}

let stubs: Stubs

beforeEach(() => {
  stubs = stubValidity()
})

afterEach(() => {
  stubs.restore()
  vi.clearAllMocks()
})

describe('checkRequiredInput', () => {
  it('returns true without touching validity when the input has a non-empty value', () => {
    const input = document.createElement('input')
    input.value = 'Max Mustermann'

    expect(checkRequiredInput(input, 'Pflichtfeld')).toBe(true)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })

  it('treats a whitespace-only value as empty', () => {
    const input = document.createElement('input')
    input.value = '   '

    expect(checkRequiredInput(input, 'Pflichtfeld')).toBe(false)
    expect(stubs.set.Input).toHaveBeenCalledWith('Pflichtfeld')
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('sets the custom validity message and calls reportValidity when the input is empty', () => {
    const input = document.createElement('input')

    expect(checkRequiredInput(input, 'Bitte Namen angeben')).toBe(false)
    expect(stubs.set.Input).toHaveBeenCalledWith('Bitte Namen angeben')
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('propagates reportValidity return: returns true when reportValidity returns true', () => {
    stubs.report.Input.mockReturnValue(true)
    const input = document.createElement('input')
    expect(checkRequiredInput(input, 'Pflichtfeld')).toBe(true)
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('works for HTMLTextAreaElement and propagates the error message', () => {
    const textarea = document.createElement('textarea')

    expect(checkRequiredInput(textarea, 'Bitte Nachricht angeben')).toBe(false)
    expect(stubs.set.Textarea).toHaveBeenCalledWith('Bitte Nachricht angeben')
    expect(stubs.report.Textarea).toHaveBeenCalledTimes(1)
  })

  it('returns true for null input without touching the prototype', () => {
    expect(checkRequiredInput(null, 'Pflichtfeld')).toBe(true)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })

  it('returns true for undefined input without touching the prototype', () => {
    expect(checkRequiredInput(undefined, 'Pflichtfeld')).toBe(true)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })
})

describe('checkRequiredSelect', () => {
  it('returns true without touching validity when a value is selected', () => {
    const select = document.createElement('select')
    const option = document.createElement('option')
    option.value = 'general'
    select.append(option)
    select.value = 'general'

    expect(checkRequiredSelect(select, 'Bitte auswählen')).toBe(true)
    expect(stubs.set.Select).not.toHaveBeenCalled()
    expect(stubs.report.Select).not.toHaveBeenCalled()
  })

  it('sets the custom validity message and reports validity for an empty value', () => {
    const select = document.createElement('select')

    expect(checkRequiredSelect(select, 'Bitte Auswahl treffen')).toBe(false)
    expect(stubs.set.Select).toHaveBeenCalledWith('Bitte Auswahl treffen')
    expect(stubs.report.Select).toHaveBeenCalledTimes(1)
  })

  it('treats a whitespace-only option value as empty', () => {
    const select = document.createElement('select')
    const option = document.createElement('option')
    option.value = '   '
    select.append(option)
    select.value = '   '

    expect(checkRequiredSelect(select, 'Pflichtfeld')).toBe(false)
    expect(stubs.set.Select).toHaveBeenCalledWith('Pflichtfeld')
    expect(stubs.report.Select).toHaveBeenCalled()
  })

  it('propagates reportValidity return: returns true when reportValidity returns true', () => {
    stubs.report.Select.mockReturnValue(true)
    const select = document.createElement('select')
    expect(checkRequiredSelect(select, 'Pflichtfeld')).toBe(true)
    expect(stubs.report.Select).toHaveBeenCalledTimes(1)
  })

  it('returns true for null select without touching the prototype', () => {
    expect(checkRequiredSelect(null, 'Pflichtfeld')).toBe(true)
    expect(stubs.set.Select).not.toHaveBeenCalled()
  })

  it('returns true for undefined select without touching the prototype', () => {
    expect(checkRequiredSelect(undefined, 'Pflichtfeld')).toBe(true)
    expect(stubs.set.Select).not.toHaveBeenCalled()
  })
})

describe('validateIbanInput', () => {
  it('accepts a syntactically valid IBAN and returns true without touching validity', () => {
    const input = document.createElement('input')
    input.value = VALID_IBAN

    expect(validateIbanInput(input)).toBe(true)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })

  it('accepts a valid IBAN written without spaces', () => {
    const input = document.createElement('input')
    input.value = VALID_IBAN.replace(/\s/g, '')

    expect(validateIbanInput(input)).toBe(true)
  })

  it('accepts a valid IBAN regardless of letter case', () => {
    const input = document.createElement('input')
    input.value = 'de89 3704 0044 0532 0130 00'

    expect(validateIbanInput(input)).toBe(true)
  })

  it('sets the custom validity message and reports for an invalid IBAN', () => {
    const input = document.createElement('input')
    input.value = MALFORMED_IBAN

    expect(validateIbanInput(input)).toBe(false)
    expect(stubs.set.Input).toHaveBeenCalledWith(IBAN_ERROR)
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('rejects a non-IBAN string of random characters', () => {
    const input = document.createElement('input')
    input.value = 'not-an-iban'

    expect(validateIbanInput(input)).toBe(false)
    expect(stubs.set.Input).toHaveBeenCalledWith(IBAN_ERROR)
    expect(stubs.report.Input).toHaveBeenCalled()
  })

  it('propagates reportValidity return on invalid IBAN', () => {
    stubs.report.Input.mockReturnValue(true)
    const input = document.createElement('input')
    input.value = MALFORMED_IBAN

    expect(validateIbanInput(input)).toBe(true)
    expect(stubs.set.Input).toHaveBeenCalledWith(IBAN_ERROR)
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('treats an empty input as invalid: sets the message, reports, returns false', () => {
    const input = document.createElement('input')

    expect(validateIbanInput(input)).toBe(false)
    expect(stubs.set.Input).toHaveBeenCalledWith(IBAN_ERROR)
    expect(stubs.report.Input).toHaveBeenCalledTimes(1)
  })

  it('returns false and does not touch validity for null input', () => {
    expect(validateIbanInput(null)).toBe(false)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })

  it('returns false and does not touch validity for undefined input', () => {
    expect(validateIbanInput(undefined)).toBe(false)
    expect(stubs.set.Input).not.toHaveBeenCalled()
    expect(stubs.report.Input).not.toHaveBeenCalled()
  })
})

describe('clearCustomValidityOnInput', () => {
  it('clears the custom validity when the user types a non-empty value', () => {
    const input = document.createElement('input')
    clearCustomValidityOnInput(input)

    input.value = 'Max'
    input.dispatchEvent(new Event('input'))

    expect(stubs.set.Input).toHaveBeenCalledWith('')
  })

  it('does not clear the validity when the value trims to empty', () => {
    const input = document.createElement('input')
    clearCustomValidityOnInput(input)

    input.value = '   '
    input.dispatchEvent(new Event('input'))

    expect(stubs.set.Input).not.toHaveBeenCalled()
  })

  it('works for HTMLTextAreaElement: clears once a value is typed', () => {
    const textarea = document.createElement('textarea')
    clearCustomValidityOnInput(textarea)

    textarea.value = 'Hello'
    textarea.dispatchEvent(new Event('input'))

    expect(stubs.set.Textarea).toHaveBeenCalledWith('')
  })

  it('no-ops before any input event is dispatched', () => {
    const input = document.createElement('input')
    clearCustomValidityOnInput(input)

    expect(stubs.set.Input).not.toHaveBeenCalled()
  })

  it('silently swallows null input (no listener is attached)', () => {
    expect(() => clearCustomValidityOnInput(null)).not.toThrow()
    expect(stubs.set.Input).not.toHaveBeenCalled()
  })

  it('silently swallows undefined input (no listener is attached)', () => {
    expect(() => clearCustomValidityOnInput(undefined)).not.toThrow()
    expect(stubs.set.Input).not.toHaveBeenCalled()
  })
})

describe('clearCustomValidityOnSelect', () => {
  it('clears the custom validity when the user selects a non-empty value', () => {
    const select = document.createElement('select')
    const option = document.createElement('option')
    option.value = 'general'
    select.append(option)

    clearCustomValidityOnSelect(select)

    select.value = 'general'
    select.dispatchEvent(new Event('change'))

    expect(stubs.set.Select).toHaveBeenCalledWith('')
  })

  it('does not clear the validity when the selected value trims to empty', () => {
    const select = document.createElement('select')
    const option = document.createElement('option')
    option.value = '   '
    select.append(option)

    clearCustomValidityOnSelect(select)

    select.value = '   '
    select.dispatchEvent(new Event('change'))

    expect(stubs.set.Select).not.toHaveBeenCalled()
  })

  it('no-ops before any change event is dispatched', () => {
    const select = document.createElement('select')
    clearCustomValidityOnSelect(select)

    expect(stubs.set.Select).not.toHaveBeenCalled()
  })

  it('silently swallows null select (no listener is attached)', () => {
    expect(() => clearCustomValidityOnSelect(null)).not.toThrow()
    expect(stubs.set.Select).not.toHaveBeenCalled()
  })

  it('silently swallows undefined select (no listener is attached)', () => {
    expect(() => clearCustomValidityOnSelect(undefined)).not.toThrow()
    expect(stubs.set.Select).not.toHaveBeenCalled()
  })
})

